/* Read-only EIP-1193 integration. No signing, approvals, or transfers. */
(function(root){'use strict';
const CHAIN={chainId:'0x1237',chainName:'Robinhood Chain',nativeCurrency:{name:'Ether',symbol:'ETH',decimals:18},rpcUrls:['https://rpc.mainnet.chain.robinhood.com'],blockExplorerUrls:['https://robinhoodchain.blockscout.com']};
const KNOWN=[{address:'0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73',symbol:'WETH',name:'Wrapped Ether',decimals:18},{address:'0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168',symbol:'USDG',name:'Global Dollar',decimals:18}];
const isAddress=a=>typeof a==='string'&&/^0x[0-9a-fA-F]{40}$/.test(a);
function format(raw,decimals){if(!Number.isInteger(decimals)||decimals<0||decimals>255)throw Error('Invalid decimals');const n=BigInt(raw);if(n<0n)throw Error('Invalid balance');const s=n.toString().padStart(decimals+1,'0');return decimals?(s.slice(0,-decimals)+'.'+s.slice(-decimals).replace(/0+$/,'')).replace(/\.$/,''):s}
function decodeText(hex){if(typeof hex!=='string'||!/^0x[0-9a-f]*$/i.test(hex)||hex.length>32770)throw Error('Invalid metadata');const bytes=Uint8Array.from(hex.slice(2).match(/.{2}/g)||[],x=>parseInt(x,16));let data=bytes;if(bytes.length>32){const word=at=>Number(BigInt('0x'+hex.slice(2+at*2,2+(at+32)*2)));const off=word(0);if(off+32>bytes.length)throw Error('Invalid metadata');const len=word(off);if(len>256||off+32+len>bytes.length)throw Error('Invalid metadata');data=bytes.slice(off+32,off+32+len)}return new TextDecoder().decode(data).replace(/[\u0000-\u001f\u007f]/g,'').slice(0,80)}
function explain(e){const c=e?.code??e?.data?.originalError?.code;if(c===4001)return 'Request declined in your wallet. You can try again.';if(c===-32002)return 'A wallet request is already open. Complete it in your wallet.';if(c===4200||c===-32601)return 'This wallet does not support that request. Switch the network manually or choose another wallet.';if(c===4900||c===4901)return 'Wallet disconnected from the network. Reconnect and retry.';return e?.message==='STALE_SESSION'?'Account or network changed. Refresh and retry.':'Could not complete the wallet request. Check your wallet and network, then retry.'}
async function request(p,method,params=[]){if(!['eth_chainId','eth_accounts','eth_getBalance','eth_call'].includes(method))return p.request({method,params});let timer;try{return await Promise.race([p.request({method,params}),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Wallet read timed out')),20000)})])}finally{clearTimeout(timer)}}
async function connect(p){const accounts=await request(p,'eth_requestAccounts');if(!isAddress(accounts?.[0]))throw Error('No valid account');return {address:accounts[0],chainId:await request(p,'eth_chainId')}}
async function switchChain(p){try{await request(p,'wallet_switchEthereumChain',[{chainId:CHAIN.chainId}])}catch(e){if((e?.code??e?.data?.originalError?.code)!==4902)throw e;await request(p,'wallet_addEthereumChain',[CHAIN]);await request(p,'wallet_switchEthereumChain',[{chainId:CHAIN.chainId}])}if(BigInt(await request(p,'eth_chainId'))!==4663n)throw Error('Wrong network')}
async function metadata(p,address){if(!isAddress(address))throw Error('Invalid address');const call=data=>request(p,'eth_call',[{to:address,data},'latest']);const [dec,sym,name]=await Promise.all([call('0x313ce567'),call('0x95d89b41'),call('0x06fdde03').catch(()=>null)]);const decimals=Number(BigInt(dec));if(!Number.isInteger(decimals)||decimals<0||decimals>255)throw Error('Invalid decimals');const symbol=decodeText(sym);if(!symbol)throw Error('Missing symbol');return {address,decimals,symbol,name:name?decodeText(name):symbol}}
async function discover(address,fetcher,signal){let url=`${CHAIN.blockExplorerUrls[0]}/api/v2/addresses/${address}/tokens?type=ERC-20`,tokens=[],complete=false;for(let page=0;page<10;page++){const r=await fetcher(url,{signal:signal?AbortSignal.any([signal,AbortSignal.timeout(12000)]):AbortSignal.timeout(12000),credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Discovery unavailable');const data=await r.json();if(!Array.isArray(data.items))throw Error('Invalid discovery response');for(const item of data.items){const t=item.token,decimals=Number(t?.decimals);if(t?.type!=='ERC-20'||!isAddress(t.address_hash)||t.decimals==null||!Number.isInteger(decimals)||decimals<0||decimals>255)continue;tokens.push({address:t.address_hash,symbol:String(t.symbol||'TOKEN').slice(0,30),name:String(t.name||'Token').slice(0,80),decimals})}if(!data.next_page_params){complete=true;break}url=`${CHAIN.blockExplorerUrls[0]}/api/v2/addresses/${address}/tokens?${new URLSearchParams({...data.next_page_params,type:'ERC-20'})}`}return {tokens,complete}}
async function balances(p,address,{discoverTokens=false,fetcher=globalThis.fetch,signal,custom=[]}={}){
if(BigInt(await request(p,'eth_chainId'))!==4663n)throw Error('Wrong network');const rows=[],warnings=[];const native=await request(p,'eth_getBalance',[address,'latest']);rows.push({address:null,symbol:'ETH',name:'Ether',decimals:18,raw:BigInt(native).toString(),balance:format(native,18),verified:true});let list=[...KNOWN,...custom];
if(discoverTokens){try{const d=await discover(address,fetcher,signal);list.push(...d.tokens);if(!d.complete)warnings.push('Discovery reached its page limit. Some tokens may be missing.')}catch(e){if(signal?.aborted)throw e;warnings.push('Token discovery unavailable. Showing canonical tokens and manually added contracts only.')}}else warnings.push('Showing ETH, canonical tokens, and manually added contracts. Enable discovery to find other indexed assets.');
const unique=[...new Map(list.map(t=>[t.address.toLowerCase(),t])).values()];if(unique.length>200)warnings.push('Showing the first 200 token contracts. Add a missing contract manually.');let failed=0;
for(let i=0;i<Math.min(unique.length,200);i+=4){if(signal?.aborted)throw Error('STALE_SESSION');const results=await Promise.allSettled(unique.slice(i,Math.min(i+4,200)).map(async t=>{const [raw,dec]=await Promise.all([request(p,'eth_call',[{to:t.address,data:'0x70a08231'+address.slice(2).toLowerCase().padStart(64,'0')},'latest']),request(p,'eth_call',[{to:t.address,data:'0x313ce567'},'latest'])]);const decimals=Number(BigInt(dec));return {...t,decimals,raw:BigInt(raw).toString(),balance:format(raw,decimals),verified:KNOWN.some(k=>k.address.toLowerCase()===t.address.toLowerCase())}}));for(const r of results){if(r.status==='fulfilled')rows.push(r.value);else failed++}}
if(failed)warnings.push(`${failed} token balance read(s) failed; omitted assets are not assumed to be zero.`);const [chain,accounts]=await Promise.all([request(p,'eth_chainId'),request(p,'eth_accounts')]);if(BigInt(chain)!==4663n||!isAddress(accounts?.[0])||accounts[0].toLowerCase()!==address.toLowerCase())throw Error('STALE_SESSION');return {rows,warnings}}
const api={CHAIN,KNOWN,isAddress,format,decodeText,explain,connect,switchChain,metadata,discover,balances};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.NullisWallet=api;
})(globalThis);

